"""Opening content for English B1, B2, C1 and C2 grammar pages (used by add_gv_open.py).
Each entry: theme chip, question, 4 gap lines (subject, answer, rest), formula pairs, formula label."""

def L(subj, ans, tail=""):
    return (subj, ans, tail, "")

def _p(theme, q, lines, formula, label):
    return dict(theme=theme, title=q + " Think of the word, then ", people=[], lines=lines, formula=(label, formula))

